select private.seed_lang_examples('ja', 'ja', $doc${"official":{"display_name":"PinWith 公式","bio":"PinWithチームが作ったおすすめリストをお届けします。"},"samples":[{"display_name":"サンプルユーザー1","bio":"友だちと旅行を計画する様子を見せるために、PinWithが作成したサンプルアカウントです。"},{"display_name":"サンプルユーザー2","bio":"友だちと旅行を計画する様子を見せるために、PinWithが作成したサンプルアカウントです。"},{"display_name":"サンプルユーザー3","bio":"友だちと旅行を計画する様子を見せるために、PinWithが作成したサンプルアカウントです。"}],"lists":[{"role":"plain","owner":"official","slug":"tokyo-shitamachi-walk","kind":"course","title":"東京下町さんぽ 谷中から清澄白河まで","desc":"谷根千の路地から上野・浅草、隅田川を渡って清澄白河へ。昔ながらの東京を一日かけて歩く定番コースです。","themes":["下町","さんぽ","東京","日帰り","定番"],"sections":[{"name":"午前：谷中・上野","by":"official","items":[{"place_id":"ChIJPYwFnNGNGGARYEeXwiYQPe8","title":"谷中銀座","memo":"日暮里駅から歩いてすぐ。夕やけだんだんの階段から商店街を見下ろすのが定番で、食べ歩きは午前中の空いている時間がおすすめ。","tags":["商店街","食べ歩き"],"lat":35.727697,"lng":139.765723},{"place_id":"ChIJh7eDrwCPGGARCs9fpCkKS2U","title":"アメ横","memo":"上野〜御徒町の高架下に続く市場。乾物やフルーツ串をつまみながら歩けて、夕方は混むので昼前に通るのが楽。","tags":["市場","食べ歩き"],"lat":35.710068,"lng":139.774601}]},{"name":"昼：浅草・押上","by":"official","items":[{"place_id":"ChIJ8T1GpMGOGGARDYGSgpooDWw","title":"浅草寺","memo":"雷門から仲見世を抜けて本堂へ。ライトアップされる夜も雰囲気が良いので、混雑が苦手なら朝か夜に。","tags":["寺社","定番"],"lat":35.714765,"lng":139.796655},{"place_id":"ChIJ35ov0dCOGGARKvdDH7NPHX0","title":"東京スカイツリー","memo":"浅草から隅田川を渡って徒歩圏。展望台は晴れた日の夕方が狙い目で、下のソラマチでお土産探しもできます。","tags":["展望","夜景"],"lat":35.710063,"lng":139.8107}]},{"name":"午後：隅田川〜清澄白河","by":"official","items":[{"place_id":"ChIJG9groLGPGGARJdySUzVkeSw","title":"蔵前橋","memo":"隅田川沿いのテラスを歩くとスカイツリーと川の景色がきれい。蔵前周辺は雑貨店やカフェも多く寄り道にぴったり。","tags":["隅田川","散歩"],"lat":35.70095,"lng":139.793463},{"place_id":"ChIJVVVp3BaJGGARfAgSR2yEybw","title":"ブルーボトルコーヒー 清澄白河","memo":"倉庫を改装した日本1号店。歩き疲れたらここで一息、近くの清澄庭園と合わせて回るのがおすすめ。","tags":["カフェ","コーヒー"],"lat":35.677756,"lng":139.800589},{"place_id":"ChIJW2cLzSGLGGARXAKXv6EkbqI","title":"築地場外市場","memo":"最後は少し足をのばして築地へ。お店は早めに閉まるところが多いので、朝ごはんに回す日程にするのも手です。","tags":["市場","海鮮"],"lat":35.66477,"lng":139.770252}]}],"comments":[]},{"role":"creator","owner":"official","slug":"otaru-vlog-day-trip","kind":"course","title":"【Vlog】小樽ひとり旅 運河と坂道の一日","desc":"札幌からJRで気軽に行ける小樽を一日で。動画で回ったルートを、撮影のコツとベストな時間帯つきでまとめました。","themes":["Vlog","小樽","北海道","撮影スポット","ひとり旅"],"sections":[{"name":"朝：駅前〜市場","by":"official","items":[{"place_id":"ChIJ52td3KzhCl8RckhF7-d8tv0","title":"三角市場","memo":"小樽駅のすぐ横。動画の冒頭で食べた海鮮丼はここ！朝早めに行くと待たずに入れました。","tags":["海鮮丼","朝ごはん"],"lat":43.199036,"lng":140.993927},{"place_id":"ChIJWeXyqVLgCl8R-gfEYqF70j0","title":"旧国鉄手宮線跡","memo":"線路の上を歩ける散策路で、レトロな雰囲気がそのまま残っています。線路をローアングルで撮ると奥行きが出て映えます。","tags":["レトロ","撮影"],"lat":43.199064,"lng":140.998736}]},{"name":"昼：運河と堺町","by":"official","items":[{"place_id":"ChIJ0UxVV2ThCl8RIZdpda0H7gQ","title":"小樽運河","memo":"浅草橋あたりから倉庫群を入れて撮るのが定番構図。人が少ない朝か、ガス灯がともる夕暮れがいちばんきれいです。","tags":["定番","夕景"],"lat":43.199041,"lng":141.002118},{"place_id":"ChIJ-UtLQMjhCl8RxEFYf8fbYE4","title":"堺町通り","memo":"ガラス工房やオルゴール堂、スイーツ店が並ぶ通り。動画の途中で食べ比べしたソフトクリームもこの通りで買いました。","tags":["食べ歩き","ガラス"],"lat":43.195283,"lng":141.004483},{"place_id":"ChIJOVEQOszjCl8RUlCv_IuaabQ","title":"青の洞窟","memo":"夏季限定のボートツアーで行ける絶景。波が高いと欠航するので、天気予報を見て前日までに予約を。カメラは防水対策必須です。","tags":["夏限定","絶景"],"lat":43.226483,"lng":140.927714}]},{"name":"夕方〜夜：高台から夜景","by":"official","items":[{"place_id":"ChIJNZSPr8LgCl8R_ro2ttgpg7U","title":"天狗山ロープウェイ","memo":"山頂から小樽の街と港が一望できます。日没30分前に上がると夕景から夜景まで撮れて、冬はスキー場としても楽しめます。","tags":["夜景","冬もOK"],"lat":43.177608,"lng":140.97524},{"place_id":"ChIJmbevaarhCl8RBMMga1H1cYw","title":"旭展望台","memo":"車があるならこちらも穴場。観光客が少なく、三脚を立ててゆっくり夜景を撮れました。冬は道が凍るので注意。","tags":["穴場","夜景"],"lat":43.197071,"lng":140.984581}]}],"comments":[]},{"role":"friends","owner":"ex1","slug":"seoul-3days-with-friends","kind":"collection","title":"3人でソウル2泊3日","desc":"友だち3人で行きたい場所をそれぞれ持ち寄ったソウル旅行リスト。最終的なルートは「Nソウルタワー」のコメントにまとめました！","themes":["ソウル","韓国旅行","女子旅","2泊3日","友だち旅"],"sections":[{"name":"サンプルユーザー1：王宮と韓屋エリア","by":"ex1","items":[{"place_id":"ChIJod7tSseifDUR9hXHLFNGMIs","title":"景福宮","memo":"韓服を着ていくと入場無料になるはず。守門将交代式も見たい！","tags":["王宮","韓服"],"lat":37.579617,"lng":126.977041},{"place_id":"ChIJT8H4r9qifDURmuXJ_6m6vM0","title":"北村韓屋村","memo":"住宅街なので静かに見学。景福宮から歩いて行ける距離。","tags":["韓屋","散歩"],"lat":37.58147,"lng":126.984952},{"place_id":"ChIJe4Jbot2ifDUR2zWhruwyaow","title":"益善洞","memo":"韓屋を改装したカフェがたくさん。路地が細いので週末は混みがち。","tags":["カフェ","韓屋"],"lat":37.573713,"lng":126.990127}]},{"name":"サンプルユーザー2：食べたいもの","by":"ex2","items":[{"place_id":"ChIJm3V0fu2ifDURRJ8IMUijVtY","title":"広蔵市場","memo":"ピンデトッとユッケは絶対食べたい。屋台はカード不可の店もあるので現金も少し持っていこう。","tags":["市場","屋台"],"lat":37.570039,"lng":126.999604},{"place_id":"ChIJ_TLjgiSjfDURnctlL07vfJo","title":"タッカンマリ通り","memo":"東大門の近く。最後に麺を入れるのが楽しみ。","tags":["鶏料理","夕ごはん"],"lat":37.570363,"lng":127.005761},{"place_id":"ChIJqb-ne_CifDURR-yH8a3sjXM","title":"明洞","memo":"コスメ巡りと夜の屋台。ホテルも明洞あたりにすると移動が楽そう。","tags":["コスメ","買い物"],"lat":37.561669,"lng":126.985844}]},{"name":"サンプルユーザー3：トレンドと夜景","by":"ex3","items":[{"place_id":"ChIJHb1ypJWkfDURb2d4XCjLluM","title":"カフェ・オニオン 聖水","memo":"工場跡のおしゃれカフェ。パンが売り切れる前、午前中に行きたい。","tags":["カフェ","聖水"],"lat":37.544733,"lng":127.058209},{"place_id":"ChIJ68AiKsWYfDUROpTctLKtxtU","title":"弘大","memo":"ストリートライブと古着屋。夜のほうがにぎやか。","tags":["夜遊び","古着"],"lat":37.556197,"lng":126.925034},{"place_id":"ChIJ8xRYr29FezUR3AtFqx2pIlw","title":"東大門デザインプラザ（DDP）","memo":"夜のライトアップが近未来っぽくて写真映えする。","tags":["建築","夜景"],"lat":37.566526,"lng":127.009224},{"place_id":"ChIJqWqOqFeifDURpYJ5LnxX-Fw","title":"Nソウルタワー","memo":"南山の上から夜景！ケーブルカーかバスで上がれる。","tags":["夜景","定番"],"lat":37.551169,"lng":126.988227}]}],"comments":[{"place_id":"ChIJod7tSseifDUR9hXHLFNGMIs","by":"ex1","body":"景福宮は火曜休みらしいから、日程の曜日だけ確認しよ！韓服レンタルするなら朝イチがいいかも","replies":[{"by":"ex2","body":"1日目は水曜だから大丈夫！韓服着たまま北村と益善洞まで歩いちゃおう"},{"by":"ex3","body":"賛成〜。益善洞でお昼にすれば午前でまとまるね"}]},{"place_id":"ChIJHb1ypJWkfDURb2d4XCjLluM","by":"ex3","body":"聖水のオニオンは開店直後が空いてるらしい。2日目の朝イチどう？","replies":[{"by":"ex1","body":"明洞から地下鉄で30分くらいだし行けそう。そのまま聖水の雑貨屋さんも回りたい"}]},{"place_id":"ChIJm3V0fu2ifDURRJ8IMUijVtY","by":"ex2","body":"広蔵市場とタッカンマリ、両方同じ日に入れると食べすぎるかな笑","replies":[{"by":"ex3","body":"広蔵市場はお昼に軽く、タッカンマリは夜ってことで！近いから移動も楽だし"},{"by":"ex1","body":"そのあとDDPのライトアップ見て帰れば完璧じゃん"}]},{"place_id":"ChIJ68AiKsWYfDUROpTctLKtxtU","by":"ex3","body":"最終日、帰りの便が夕方だから弘大は無理かも…","replies":[{"by":"ex2","body":"じゃあ弘大は2日目の夜にしよ。空港鉄道も弘大入口から乗れるし最終日は明洞で買い物だけにする？"},{"by":"ex3","body":"それでいこう！スーツケースはホテルに預けておけばOK"}]},{"place_id":"ChIJqWqOqFeifDURpYJ5LnxX-Fw","by":"ex1","body":"【最終プラン】1日目：景福宮（韓服）→北村→益善洞ランチ→夜はNソウルタワーで夜景。2日目：朝オニオン聖水→広蔵市場ランチ→タッカンマリ→DDP→弘大。3日目：明洞で買い物→夕方の便で帰国。予算は1人1日1万円くらいで！","replies":[{"by":"ex2","body":"完璧！雨だったらタワーは2日目と入れ替えよう"},{"by":"ex3","body":"了解〜！ケーブルカーは混むからバスで行こうね"}]}]},{"role":"food","owner":"official","slug":"osaka-konamon-kushikatsu","kind":"collection","title":"大阪ミナミ＆新世界 粉もん・串カツはしご","desc":"お好み焼き、串カツ、市場の食べ歩き。大阪らしい味をミナミと新世界でまとめてはしごできるリストです。","themes":["大阪グルメ","粉もん","串カツ","食べ歩き","はしご酒"],"sections":[{"name":"ミナミ：道頓堀・なんば","by":"official","items":[{"place_id":"ChIJg2DcJhXnAGARCbeAHoZrPeQ","title":"道頓堀","memo":"グリコ看板の前から食べ歩きスタート。たこ焼きは店ごとに焼き方が違うので、少量ずつ食べ比べるのがおすすめ。","tags":["食べ歩き","たこ焼き"],"lat":34.668647,"lng":135.503098},{"place_id":"ChIJxV-0lRTnAGARLxnGwRLjnwI","title":"お好み焼き 三平（法善寺）","memo":"法善寺横丁の石畳エリアにあるお好み焼き店。食後に水掛不動さんへお参りするのが定番の流れ。","tags":["お好み焼き","法善寺横丁"],"lat":34.668233,"lng":135.502703},{"place_id":"ChIJvRX1cBPnAGARzhcHALQCKbw","title":"味乃家 本店","memo":"なんばの人気お好み焼き店で、行列ができやすいので開店直後か遅めの時間が狙い目。","tags":["お好み焼き","行列店"],"lat":34.668065,"lng":135.500976},{"place_id":"ChIJcQeDV2rnAGARs1a1-jZ5MQs","title":"福太郎 本店","memo":"千日前のお好み焼き・ねぎ焼きの名店。ねぎ焼きはお好み焼きとは違う軽さがあるので、2人ならシェアして両方頼むのがおすすめ。","tags":["ねぎ焼き","お好み焼き"],"lat":34.665592,"lng":135.504538},{"place_id":"ChIJXSJB5UHnAGARQcEjvngsHaw","title":"黒門市場","memo":"「大阪の台所」と呼ばれる市場。海鮮の串や果物をつまめて、夕方は閉まる店も多いので昼までに行くのが安心。","tags":["市場","海鮮"],"lat":34.665351,"lng":135.506242},{"place_id":"ChIJgVaOpOvnAGAR00_cj2VaSmc","title":"串かつ 一徳 道頓堀本店","memo":"新世界まで行けない日はミナミで串カツを。ソースの二度漬けは禁止なので、キャベツですくうのが大阪流。","tags":["串カツ","ミナミ"],"lat":34.668802,"lng":135.503081}]},{"name":"新世界：通天閣のまわり","by":"official","items":[{"place_id":"ChIJeb2_BWDnAGARy0zq5dYoSfE","title":"串かつ 一徳 本店","memo":"通天閣のおひざもとで揚げたてを。カウンター席なら注文した串がすぐ出てきて、少しずつ頼めます。","tags":["串カツ","新世界"],"lat":34.65102,"lng":135.505833},{"place_id":"ChIJ5V4HCWDnAGARd6bIaaK91O4","title":"串かつだるま","memo":"新世界の串カツといえばここ。二度漬け禁止の共用ソースが名物で、どて焼きと一緒に頼むのが定番です。","tags":["串カツ","定番"],"lat":34.65157,"lng":135.506203}]}],"comments":[]}]}$doc$::jsonb);
